// expect: pass
// Rust 1.100: `!` is a type you can name, and Infallible is now `!`.
fn byte_len(input: &str) -> Result<usize, !> {
    Ok(input.len()) // this operation cannot fail, and the type says so
}
fn main() {
    let Ok(len) = byte_len("signal"); // no Err arm: it cannot exist
    let flag = "--verbose".trim_prefix("--");
    println!("{len} bytes, flag {flag}");
}

// expect: pass
use std::num::ParseIntError;
fn double(input: &str) -> Result<u16, ParseIntError> {
    let value: u8 = input.parse()?;
    Ok(u16::from(value) * 2)
}
fn main() -> Result<(), ParseIntError> {
    assert_eq!(double("128")?, 256);
    assert!(double("invalid").is_err());
    Ok(())
}

// expect: pass
fn main() {
    let values = [2, 4, 6];
    let total = std::thread::scope(|scope| {
        let handle = scope.spawn(|| values.iter().sum::<i32>());
        handle.join().expect("worker should not panic")
    });
    assert_eq!(total, 12);
}

// expect: pass
trait Summary { fn summary(&self) -> String; }
struct Report { count: usize }
impl Summary for Report {
    fn summary(&self) -> String { format!("{} samples", self.count) }
}
fn show(item: &impl Summary) { println!("{}", item.summary()); }
fn main() { show(&Report { count: 4 }); }
